import{_ as n,o as a,c as r,ah as s}from"./chunks/framework.D1ler-R1.js";const l="/projects/SpiderPi_Pro/en/latest/assets/image3.BHm68kg2.jpeg",c="/projects/SpiderPi_Pro/en/latest/assets/image4.BGIIj1iQ.jpeg",d="/projects/SpiderPi_Pro/en/latest/assets/image5.CCgHJijY.jpeg",o="/projects/SpiderPi_Pro/en/latest/assets/image6.D0H3u9si.jpeg",i="/projects/SpiderPi_Pro/en/latest/assets/image7.DU5uGdZJ.jpeg",g="data:image/png;base64,",h="/projects/SpiderPi_Pro/en/latest/assets/image9.BZXmJbxo.jpeg",p="/projects/SpiderPi_Pro/en/latest/assets/image10.CiZ6D0uM.jpeg",m="/projects/SpiderPi_Pro/en/latest/assets/image11.D7c4J9S8.jpeg",u="/projects/SpiderPi_Pro/en/latest/assets/image3.BHm68kg2.jpeg",A="/projects/SpiderPi_Pro/en/latest/assets/image13.DyyxYLW4.jpeg",b="/projects/SpiderPi_Pro/en/latest/assets/image14.YrQCrvnq.jpeg",P="/projects/SpiderPi_Pro/en/latest/assets/image5.CCgHJijY.jpeg",y="/projects/SpiderPi_Pro/en/latest/assets/image18.DwlqJ4kA.jpeg",f="/projects/SpiderPi_Pro/en/latest/assets/image19.DMFOKP84.jpeg",w="/projects/SpiderPi_Pro/en/latest/assets/image20.B_J8UPmx.jpeg",k="/projects/SpiderPi_Pro/en/latest/assets/image10.CiZ6D0uM.jpeg",C="/projects/SpiderPi_Pro/en/latest/assets/image1.C2CtM_ix.jpeg",I="/projects/SpiderPi_Pro/en/latest/assets/image2.Cz3FoOj1.png",q="/projects/SpiderPi_Pro/en/latest/assets/image4.CM47SaFw.png",z="/projects/SpiderPi_Pro/en/latest/assets/image5.CUYWXk-R.png",S="/projects/SpiderPi_Pro/en/latest/assets/image6.CL_434im.png",x="/projects/SpiderPi_Pro/en/latest/assets/image7.DhwBbFuE.png",v="/projects/SpiderPi_Pro/en/latest/assets/image8.Cz0ZlJCF.png",T="/projects/SpiderPi_Pro/en/latest/assets/image9.PhcqmXbG.png",E="/projects/SpiderPi_Pro/en/latest/assets/image10.Dy10w6MY.png",j="/projects/SpiderPi_Pro/en/latest/assets/image11.CDtwkgXS.png",_="/projects/SpiderPi_Pro/en/latest/assets/image12.BbZ2g5ah.jpeg",t="data:image/png;base64,",Q="/projects/SpiderPi_Pro/en/latest/assets/image14.DQQCJ_Y3.png",R="/projects/SpiderPi_Pro/en/latest/assets/image15.mJm6fQap.png",W="/projects/SpiderPi_Pro/en/latest/assets/image16.B6YXh-Q_.png",B="/projects/SpiderPi_Pro/en/latest/assets/image17.Bmulr23R.png",F="/projects/SpiderPi_Pro/en/latest/assets/image18.CAxTfRUF.png",J="data:image/png;base64,",O="/projects/SpiderPi_Pro/en/latest/assets/image20.BmBhft0f.png",N="/projects/SpiderPi_Pro/en/latest/assets/image21.BIc4FNdl.png",D="/projects/SpiderPi_Pro/en/latest/assets/image22.CESyxUyx.png",M="/projects/SpiderPi_Pro/en/latest/assets/image23.DpDKF9Pb.png",U="/projects/SpiderPi_Pro/en/latest/assets/image24.BY1DH3vV.png",L="data:image/png;base64,",H="/projects/SpiderPi_Pro/en/latest/assets/image26.C7T7eEEC.png",X="/projects/SpiderPi_Pro/en/latest/assets/image19.CUlRe7BJ.png",V="/projects/SpiderPi_Pro/en/latest/assets/image20.Dsz6Cz8f.png",G="/projects/SpiderPi_Pro/en/latest/assets/image21.BtQhasHW.png",K="/projects/SpiderPi_Pro/en/latest/assets/image22.mP2-qF-l.png",Y="/projects/SpiderPi_Pro/en/latest/assets/image23.CcdC4yDc.png",Z="/projects/SpiderPi_Pro/en/latest/assets/image24.BZ5f2PnW.png",$="/projects/SpiderPi_Pro/en/latest/assets/image25.CSqj5NaW.png",tt="/projects/SpiderPi_Pro/en/latest/assets/image25.CSqj5NaW.png",ct=JSON.parse('{"title":"2. Quick User Experience","description":"","frontmatter":{},"headers":[],"relativePath":"docs/2_Getting Ready.md","filePath":"docs/2_Getting Ready.md"}'),et={name:"docs/2_Getting Ready.md"};function ot(it,e,nt,at,rt,st){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="_2-quick-user-experience" tabindex="-1">2. Quick User Experience <a class="header-anchor" href="#_2-quick-user-experience" aria-label="Permalink to &quot;2. Quick User Experience&quot;">​</a></h1><p id="anchor_2_1"></p><h2 id="_2-1-app-installation-and-connection" tabindex="-1">2.1 APP Installation and Connection <a class="header-anchor" href="#_2-1-app-installation-and-connection" aria-label="Permalink to &quot;2.1 APP Installation and Connection&quot;">​</a></h2><p>The following instructions use TurboPi as an example and apply to other Hiwonder Raspberry Pi series products as well. In this section, you will learn how to use APP &quot;<strong>WonderPi</strong>&quot; to control TurboPi. The installation method is as follows.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p>① Make sure all APP permissions are turned on in settings, otherwise APP functions will be limited!</p><p>② Turn on Location and WiFi before operation.</p></div><h3 id="_2-1-1-installation" tabindex="-1">2.1.1 Installation <a class="header-anchor" href="#_2-1-1-installation" aria-label="Permalink to &quot;2.1.1 Installation&quot;">​</a></h3><p><strong><a href="https://play.google.com/store/apps/details?id=com.Wonder.Pi" target="_blank" rel="noreferrer">APP Installation Pack (Android)</a></strong></p><p><strong><a href="https://apps.apple.com/cn/app/wonderpi/id1477946178" target="_blank" rel="noreferrer">APP Installation Pack (iOS)</a></strong></p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><ul><li><p>Please turn TurboPi on before connecting.</p></li><li><p>Make sure all APP permissions are turned on in settings, otherwise APP functions will be limited!</p></li><li><p>Turn on Location and WiFi before operation.</p></li></ul></div><h3 id="_2-1-2-app-connection" tabindex="-1">2.1.2 APP Connection <a class="header-anchor" href="#_2-1-2-app-connection" aria-label="Permalink to &quot;2.1.2 APP Connection&quot;">​</a></h3><p>(1) Start robot. (The switch is on Raspberry Pi expansion board). For detailed instruction, please refer to the file in &quot;<strong><a href="https://docs.hiwonder.com/projects/SpiderPi_Pro/en/latest/docs/1_read_before_studying.html#charging-and-power-on-status-explanation" target="_blank" rel="noreferrer">Getting Ready\\1.4 Charging and Power-On Status Explanation</a></strong>&quot;.</p><p>(2) After TurboPi boots up successfully, it enters AP direct connection mode, and generates a WiFi starting with <strong>&quot;HW&quot;</strong>. Join this WiFi, and then you can experience robot games</p><ul><li><strong>Introduction to Connection Mode</strong></li></ul><p>There are two connection modes, namely direct connection mode and LAN mode. APP functions are the same under these two modes.</p><p>(1) <strong>AP direct connection mode:</strong> RaspberryPi generates a WiFi which can be connected by phones. But this WiFi has no internet access.</p><p>(2) <strong>STA LAN mode:</strong> Raspberry Pi actively connects to specific WiFi. In this mode, you can access internet.</p><ul><li><strong>Direct Connection Mode (MUST-READ)</strong></li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>After TurboPi boots up successfully, it enters AP direct connection mode, and generates a WiFi starting with <strong>&quot;HW&quot;</strong>.</p></div><p>(1) Open &quot;<strong>WonderPi</strong>&quot;. Select <strong>&quot;Standard -&gt;TurboPi&quot;</strong> in sequence.</p><img loading="lazy" src="'+l+'"><p>(2) Tap <strong>&quot;+&quot;</strong> in bottom right corner, and then select <strong>Direct Connection Mode</strong>.</p><img loading="lazy" src="'+c+'"><p>(3) Tap <strong>&quot;Go to connect device hotspot&quot;</strong>. Join WiFi starting with <strong>&quot;HW&quot;</strong>. The password is <strong>&quot;hiwonder&quot;</strong>.</p><img loading="lazy" src="'+d+'"><img loading="lazy" src="'+o+'" style="width:350px;" class="common_img"><p>(4) Return back to APP after connection.</p><img loading="lazy" src="'+i+'" style="width:350px;" class="common_img"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>For iOS user, please don&#39;t return to APP until WiFi icon appears on status bar, otherwise robot cannot be searched. If robot cannot be searched by APP, tap <img loading="lazy" height="52" width="52" src="'+g+'" style="width:45px;"> to refresh.</p></div><p>(5) APP automatically connects to robot. When robot icon below occurs, connection completes.</p><img loading="lazy" src="'+h+'"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>If you are informed of &quot;<strong>No Internet. Whether to keep connection</strong>&quot;, just select &quot;<strong>keep connected</strong>&quot;.</p></div><p>(6) Tap robot icon to enter mode selection interface.</p><img loading="lazy" src="'+p+'"><p>For detailed introduction to robot games, please refer to the file in &quot;<strong><a href="#anchor_2_2">2.2 APP Control</a></strong>&quot;.</p><h3 id="_2-2-3-lan-connection-mode" tabindex="-1">2.2.3 LAN Connection Mode <a class="header-anchor" href="#_2-2-3-lan-connection-mode" aria-label="Permalink to &quot;2.2.3  LAN Connection Mode&quot;">​</a></h3><p>(1) Disconnect the WiFi generated by TurboPi. Connect your phone to a WiFi. Take <strong>&quot;Hiwonder&quot;</strong> as example.</p><img loading="lazy" src="'+m+'" style="width:350px;" class="common_img"><p>(2) After connection, open <strong>&quot;WonderPi&quot;</strong>. Select <strong>&quot;Standard -&gt;TurboPi&quot;</strong> in sequence.</p><img loading="lazy" src="'+u+'"><p>(3) Tap <strong>&quot;+&quot;</strong> in bottom right corner, and then select LAN Mode.</p><img loading="lazy" src="'+A+'"><p>(4) Input the password of the WiFi your phone joins. Ensure the password you input is correct, otherwise APP fails to connect to robot. Tap <strong>&quot;OK&quot;</strong>.</p><img loading="lazy" src="'+b+'"><p>(5) Tap <strong>&quot;Go to connect device hotspot&quot;</strong>.</p><img loading="lazy" src="'+P+'"><p>(6) Join the WiFi starting with <strong>&quot;HW&quot;.</strong> The password is <strong>&quot;hiwonder&quot;</strong>. After connection, return back to APP.</p><img loading="lazy" src="'+o+'" style="width:48%;"><img loading="lazy" src="'+i+'" style="width:48%;"><p>(7) APP automatically configures network.</p><img loading="lazy" src="'+y+'"><p>(8) After a while, robot icon below occurs, and LED on expansion board keeps on.</p><img loading="lazy" src="'+f+'"><p>(9) Long press robot icon to check TurboPi&#39;s IP and ID.</p><img loading="lazy" src="'+w+'"><p>(10) Tap robot icon to enter mode selection interface.</p><img loading="lazy" src="'+k+'"><p>For detailed introduction to robot games, please refer to the file in&quot;<strong><a href="#anchor_2_2">2.2 APP Control</a></strong>&quot;.</p><p id="anchor_2_2"></p><h2 id="_2-2-app-control" tabindex="-1">2.2 APP Control <a class="header-anchor" href="#_2-2-app-control" aria-label="Permalink to &quot;2.2 APP Control&quot;">​</a></h2><h3 id="_2-2-1-getting-ready" tabindex="-1">2.2.1 Getting ready <a class="header-anchor" href="#_2-2-1-getting-ready" aria-label="Permalink to &quot;2.2.1 Getting ready&quot;">​</a></h3><p>Follow the tutorial in <a href="#anchor_2_1">2.1 APP Installation and Connection</a> to install the app and connect to the SpiderPi Pro.</p><h3 id="_2-2-2-start-games" tabindex="-1">2.2.2 Start Games <a class="header-anchor" href="#_2-2-2-start-games" aria-label="Permalink to &quot;2.2.2 Start Games&quot;">​</a></h3><p>After connecting, click SpiderPi Pro icon to enter the mode selection interface.</p><img loading="lazy" src="'+C+'" alt="loading"><p>In the mode selection interface, click the icon corresponding to the game to enter the game interface.</p><img loading="lazy" height="655" width="1313" src="'+I+'" alt="loading"><ul><li><strong>Robot Control</strong></li></ul><p>This game allows you to control the movement and the action group execution of the robot in real time. The interface consists of four parts, and the descriptions and function icons of each part are shown below:</p><img loading="lazy" height="658" width="1318" class="common_img" src="'+q+'" alt="loading"><p>The interface of <code>Robot Control</code> can be divided into three parts. The left side of the interface can control the movement of the SpiderPi Pro by dragging the slider. Other function icons can refer to the following table:</p><table tabindex="0"><thead><tr><th style="text-align:center;">Icon</th><th style="text-align:center;"><strong>Corresponding Function</strong></th></tr></thead><tbody><tr><td style="text-align:center;"><img loading="lazy" height="260" width="283" src="'+z+'" style="width:1.1875in;height:1.18125in;"></td><td style="text-align:center;">Drag to control SpiderPi Pro&#39;s movement.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="117" width="265" src="'+S+'" style="width:1.16667in;height:0.5in;"></td><td style="text-align:center;">Clicking on the icons from left to right can control the robot to perform left slide, stand at attention, and right slide, respectively.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="57" width="135" src="'+x+'" style="width:0.84514in;height:0.54444in;"></td><td style="text-align:center;">Make SpiderPi Pro perform provided built-in actions.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="58" width="138" src="'+v+'" style="width:1.01111in;height:0.64444in;"></td><td style="text-align:center;">Provide a guide for the remote control of the SpiderPi.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="343" width="160" src="'+T+'" style="width:0.92917in;height:1.88611in;"></td><td style="text-align:center;">Make SpiderPi Pro perform provi</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="122" width="246" src="'+E+'" style="width:2.00625in;height:0.96944in;"></td><td style="text-align:center;">Adjust SpiderPi&#39;s movement speed.</td></tr></tbody></table><p>Click the icon <img loading="lazy" height="82" width="83" src="'+j+'" style="width:0.375in;height:0.37222in;"> at the top to bring up the interface for controlling the robotic arm. The movement of the robotic arm can be controlled by adjusting the angle of its 5 servos using the buttons.</p><img loading="lazy" class="common_img" style="width:50%;" src="'+_+'" alt="loading"><p>If you want to back to the games option interface, you can click the blank area, then the title bar will appear. Next, click <img loading="lazy" height="41" width="51" src="'+t+'" style="width:0.27222in;height:0.21944in;"> at the left side.</p><ul><li><strong>Color Recognition</strong></li></ul><p>This game can recognize red, green, and blue. SpiderPi Pro will nod when it detects red and shake its head when it detects blue or green.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><ul><li><p>Please start this game under a well-lit environment, but try to keep it from direct light.</p></li><li><p>When recognizing, please do not have the same or similar colored object within the detected range to avoid interference.</p></li><li><p>If the recognition effect is not good enough, please refer to &quot;<a href="#anchor_2_2_3">2.2.3 Adjust Color Threshold</a>&quot;.</p></li></ul></div><p>(1) Click <strong>&quot;Color Recognition&quot;</strong> to enter this game. Its interface consists three parts:</p><img loading="lazy" height="685" width="1367" class="common_img" src="'+Q+'" alt="loading"><p>① The status bar is located at the top of the interface.</p><p>② The left side of the interface is the area for enabling, disabling the game and adjusting the color threshold.</p><p>③ The right side of the interface is the area for displaying the live camera feed.</p><p>(2) Click the <strong>&quot;Start&quot;</strong> allows you to place red, blue, and green objects one by one in front of the camera.</p><table tabindex="0"><thead><tr><th style="text-align:center;">Recognized Color</th><th style="text-align:center;">Outcome</th></tr></thead><tbody><tr><td style="text-align:center;">Red</td><td style="text-align:center;">The buzzer emits a &quot;beep&quot; sound, and the camera nods its head.</td></tr><tr><td style="text-align:center;">Green</td><td style="text-align:center;">The buzzer emits a &quot;beep&quot; sound, and the camera shakes its head.</td></tr><tr><td style="text-align:center;">Blue</td><td style="text-align:center;">The buzzer emits a &quot;beep&quot; sound, and the camera shakes its head.</td></tr></tbody></table><p>(3) If want to back to mode selection interface, you can arbitrarily click the blank area in interface, then click <img loading="lazy" height="41" width="51" src="'+t+'" style="width:0.31496in;height:0.31496in;">.</p><ul><li><strong>Target Tracking</strong></li></ul><p>(1) Click <strong>&quot;Target Tracking&quot;</strong> to enter the game interface. Once activated, this game enables the pan-tilt of SpiderPi Pro to move along with the movement of the target color.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p>Please start this game under a well-lit environment, but try to keep it from direct light.</p><p>When recognizing, please do not have the same or similar colored object within the detected range to avoid interference.</p><p>If the recognition effect is not good enough, please refer to &quot;<a href="#anchor_2_2_3">2.2.3 Adjust Color Threshold</a>&quot;.</p></div><img loading="lazy" height="662" width="1322" class="common_img" src="'+R+'" alt="loading"><p>① The status bar is located at the top of the interface.</p><p>② The tracking switch area is located on the left side of the interface</p><p>③ The live camera feed area is located on the right side of the interface.</p><p>(2) If want to back to mode selection interface, you can arbitrarily click the blank area in interface, then click <img loading="lazy" height="41" width="51" src="'+t+'" style="width:0.31496in;height:0.31496in;">.</p><ul><li><strong>Line Following</strong></li></ul><p>(1) Click <strong>&quot;Line Following&quot;</strong> to enter this game. After activating it, the SpiderPi Pro will move forward along a black, white or red line.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><ul><li><p>Please start this game under a well-lit environment, but try to keep it from direct light.</p></li><li><p>When recognizing, please do not have the same or similar colored object within the detected range to avoid interference.</p></li><li><p>If the recognition effect is not good enough, please refer to &quot;<a href="#anchor_2_2_3">2.2.3 Adjust Color Threshold</a>&quot;.</p></li></ul></div><img loading="lazy" height="687" width="1360" src="'+W+'" alt="loading"><p>① The status bar is located at the top of the interface.</p><p>② The line tracking switch area is located on the left side of the interface</p><p>③ The camera live feed area is located on the right side of the interface.</p><p>(2) Click <strong>&quot;Start following&quot;</strong> to enter this game and select color. Then SpiderPi will follow the targeted line.</p><table tabindex="0"><thead><tr><th style="text-align:center;">Icon Button</th><th style="text-align:center;">Function Instruction</th></tr></thead><tbody><tr><td style="text-align:center;"><img loading="lazy" height="95" width="451" src="'+B+'" style="width:1.1811in;height:0.24586in;"></td><td style="text-align:center;">Start or stop this game.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="417" width="244" src="'+F+'" style="width:0.79514in;height:1.37569in;"></td><td style="text-align:center;">Select the targeted color.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="76" width="89" src="'+J+'" style="width:0.94514in;height:0.76806in;"></td><td style="text-align:center;">Display the selected tracking color.</td></tr></tbody></table><p>(3) If want to back to mode selection interface, you can arbitrarily click the blank area in interface, then click <img loading="lazy" height="41" width="51" src="'+t+'" style="width:0.31496in;height:0.31496in;">.</p><ul><li><strong>Face Detection</strong></li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><ul><li><p>Please start this game in a well-lit environment, but keep robot from the direct light.</p></li><li><p>When recognizing, one human face only is allowed to appear within the detected range. Otherwise, it will affect the game result.</p></li><li><p>The max recognition distance is about 1 meter.</p></li></ul></div><p>(1) Click Face Recognition to enter this game.</p><img loading="lazy" height="658" width="1324" class="common_img" src="'+O+'" alt="loading"><p>(2) After clicking <code>Start</code>, the pan-tilt of the SpiderPi Pro will move left and right. When the face is detected, it will make a &quot;<strong>Hello</strong>&quot; action.</p><p>(3) If want to back to the mode selection interface, click the blank area of interface and then click<img loading="lazy" height="41" width="51" src="'+t+'" style="width:0.31496in;height:0.31496in;">in the left side.</p><ul><li><strong>Tag Recognition</strong></li></ul><p>(1) Click <strong>&quot;Tag Recognition&quot;</strong> in mode selection interface to enter this game. This allows SpiderPi Pro&#39;s camera to recognize different QR code tags and execute corresponding actions.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><ul><li><p>When recognizing QR codes, the distance should not be too close or too far. The best distance between the QR code image and the camera is 35cm.</p></li><li><p>Please start this game in a well-lit environment, but keep robot from the direct light.</p></li></ul></div><img loading="lazy" height="661" width="1324" class="common_img" src="'+N+'" alt="loading"><p>(2) Click &quot;<strong>Start</strong>&quot;. Then SpiderPi will identify tags within the detected range and carry out different actions according to the recognized ID.</p><table tabindex="0"><thead><tr><th style="text-align:center;"><strong>ID</strong></th><th style="text-align:center;">Corresponding Action</th></tr></thead><tbody><tr><td style="text-align:center;">1</td><td style="text-align:center;">Wave &quot;Hello&quot;.</td></tr><tr><td style="text-align:center;">2</td><td style="text-align:center;">Walk in place.</td></tr><tr><td style="text-align:center;">3</td><td style="text-align:center;">Twist the body.</td></tr></tbody></table><p>(3) If want to back to the mode selection interface, click the blank area of interface and then click <img loading="lazy" height="41" width="51" src="'+t+'" style="width:0.31496in;height:0.31496in;"> in the left side.</p><p><strong>2.2.7 Obstacle Avoidance</strong></p><p>(1) Click Obstacle Avoidance to enter the game interface. After this game is activated, the SpiderPi Pro can use ultrasonic to detect obstacles ahead to avoid them.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Do not detect object at close range for a long time.</p></div><img loading="lazy" height="659" width="1322" class="common_img" src="'+D+'" alt="loading"><p>① The left side of the interface includes the obstacle avoidance game switch and the obstacle threshold setting area.</p><p>② The middle of the interface is the camera transmission image area.</p><p>③ The right side of the interface includes the setting area for the RGB light and motor speed.</p><p>(2) Click <strong>&quot;Start avoidance&quot;</strong>. SpiderPi Pro will move forwards and it will turn left when detecting obstacle ahead. Then continue moving forward until there is no obstacle.</p><table tabindex="0"><thead><tr><th style="text-align:center;">Button Icon</th><th style="text-align:center;">Function Instruction</th></tr></thead><tbody><tr><td style="text-align:center;"><img loading="lazy" height="86" width="370" src="'+M+'" style="width:2.20972in;height:0.36806in;"></td><td style="text-align:center;">Start or close this game.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="109" width="219" src="'+U+'" style="width:2.2125in;height:0.87847in;"></td><td style="text-align:center;">Set obstacle threshold in the unit of mm.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="32" width="141" src="'+L+'" style="width:2.20903in;height:0.47639in;"></td><td style="text-align:center;">Turn on or off RGB light.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="191" width="204" src="'+H+'" style="width:0.92639in;height:0.87014in;"></td><td style="text-align:center;">Adjust RGB light color.</td></tr></tbody></table><p>(3) If want to back to mode selection interface, you can arbitrarily click the blank area in interface, then click <img loading="lazy" height="41" width="51" src="'+t+'" style="width:0.31496in;height:0.31496in;">.</p><p id="anchor_2_2_3"></p><h3 id="_2-3-3-adjust-color-threshold" tabindex="-1">2.3.3 Adjust Color Threshold <a class="header-anchor" href="#_2-3-3-adjust-color-threshold" aria-label="Permalink to &quot;2.3.3 Adjust Color Threshold&quot;">​</a></h3><p>(1) Select color to be adjusted. Take red as example.</p><img loading="lazy" height="517" width="1100" src="'+X+'"><p>(2) Put red object within camera recognition zone. Set L_min, a_min and b_min to 0, and L_max, a_max and b_max to 255.</p><img loading="lazy" height="530" width="1100" src="'+V+'"><p>(3) Tap &quot;<strong>Instruction</strong>&quot; icon to check how to adjust color threshold.</p><img loading="lazy" height="524" width="1100" src="'+G+'"><img loading="lazy" height="560" width="1213" src="'+K+'"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>if you need to close Instruction window, select &quot;<strong>OK</strong>&quot;.</p></div><p>(4) Red approaches &quot;<strong>+a</strong>&quot; zone, so you need to adjust A component.</p><img loading="lazy" height="300" width="300" src="'+Y+'" style="width:300px;" class="common_img"><p>(5) Keep &quot;<strong>a_max</strong>&quot; value the same, and then increase &quot;<strong>a_min</strong>&quot; value till red object turns white and other area is black.</p><img loading="lazy" height="602" width="1280" src="'+Z+'"><p>(6) Adjust &quot;<strong>L</strong>&quot; and &quot;<strong>B</strong>&quot; values. If it belongs to light red, increase L_min. Otherwise, decrease L_max. If it belongs to warm tone, increase B_min. Otherwise, decrease B_max.</p><img loading="lazy" height="602" width="1280" src="'+$+'"><p>(7) Remember to save the value after adjustment.</p><img loading="lazy" height="602" width="1280" src="'+tt+'">',144)])])}const dt=n(et,[["render",ot]]);export{ct as __pageData,dt as default};
